INSERT INTO venues (slug, name, venue_type, status, region, county, town, postcode, latitude, longitude, summary, editorial_review, tiny_dog_verdict, dogs_indoors, dogs_outdoors, dogs_throughout, covered_outdoor_seating, quiet_seating, spacious_tables, enclosed_garden, puppy_suitable, nervous_dog_suitable, multiple_dogs_welcome, escape_risk, noise_level, water_bowls, free_dog_treats, parking_available, accessible_entrance, nearby_green_space, best_visit_times, food_and_drink_summary, price_band, welcome_label, welcome_score, feature_labels, nearby_walk_slugs, verification_method, last_verified_date) VALUES
('the-magazin-serpentine-london', 'The Magazine at Serpentine North', 'cafe', 'published', 'London', 'Greater London', 'London', 'W2 2AR', 51.5075, -0.1745, 'A stylish café beside the Serpentine Gallery in Hyde Park with dog-friendly outdoor terrace and park views.', 'Set within the stunning Zaha Hadid-designed gallery extension, The Magazine offers excellent coffee and light meals. Dogs are welcome on the spacious terrace which overlooks Hyde Park. Perfect after a tiny-dog stroll around the Serpentine.', 'A sophisticated park café with generous terrace space. Ideal post-walk stop for tiny dogs exploring Hyde Park.', 'no', 'yes', 'no', 'yes', 'yes', 'yes', 'no', 'yes', 'yes', 'yes', 'low', 'relaxed', 'yes', 'no', 'no', 'yes', 'yes', 'Mid-morning weekdays', 'Specialty coffee, pastries, seasonal salads and light lunches', '£££', 'warm_little_welcome', 74, ARRAY['Warm Little Welcome', 'Perfect after walkies', 'Quiet corner available'], ARRAY['hyde-park-serpentine-loop']::text[], 'personal_visit', '2026-07-01'),

('the-spaniards-inn-hampstead', 'The Spaniards Inn', 'pub', 'published', 'London', 'Greater London', 'London', 'NW3 7JJ', 51.5720, -0.1730, 'A historic 16th-century pub on the edge of Hampstead Heath with a large beer garden and excellent dog welcome.', 'One of London''s most famous dog-friendly pubs, right at the entrance to Hampstead Heath. The sprawling garden is ideal for post-walk drinks and dogs are welcome inside the bar areas too. Proper pub food and a wide selection of ales.', 'A legendary dog pub with a huge garden. Dogs welcome inside and out — a must-visit for Heath walkers.', 'yes', 'yes', 'no', 'no', 'yes', 'yes', 'yes', 'yes', 'yes', 'yes', 'low', 'moderate', 'yes', 'yes', 'no', 'yes', 'yes', 'Weekday lunchtimes', 'Pub classics, Sunday roasts, cask ales and wines', '££', 'tiny_dog_favourite', 90, ARRAY['Tiny Dog Favourite', 'Little paws welcome inside', 'Enclosed little garden', 'Perfect after walkies'], ARRAY['hampstead-heath-parliament-hill']::text[], 'personal_visit', '2026-06-28'),

-- BIRMINGHAM
('the-canal-house-birmingham', 'The Canal House', 'pub', 'published', 'West Midlands', 'West Midlands', 'Birmingham', 'B1 2JR', 52.4785, -1.9080, 'A waterside pub overlooking the canal basin in central Birmingham with dogs welcome throughout the ground floor.', 'A stylish conversion right on the canal with floor-to-ceiling windows and a waterside terrace. Dogs are genuinely welcome throughout the ground floor. Spacious tables and a relaxed atmosphere make it comfortable for small dogs.', 'A modern canalside pub with plenty of space and a relaxed attitude to dogs. Good for tiny dogs who prefer calm environments.', 'yes', 'yes', 'no', 'yes', 'yes', 'yes', 'no', 'yes', 'yes', 'yes', 'low', 'moderate', 'yes', 'no', 'no', 'yes', 'yes', 'Weekday afternoons', 'Gastropub menu, craft beers, cocktails and weekend brunch', '££', 'warm_little_welcome', 76, ARRAY['Warm Little Welcome', 'Little paws welcome inside', 'Rainy day rescue'], ARRAY[]::text[], 'personal_visit', '2026-06-15'),

('faculty-coffee-birmingham', 'Faculty Coffee', 'cafe', 'published', 'West Midlands', 'West Midlands', 'Birmingham', 'B3 1JJ', 52.4820, -1.9010, 'A specialty coffee shop in the Jewellery Quarter with dogs welcome inside and a calm, focused atmosphere.', 'Faculty is a respected specialty roaster in the Jewellery Quarter. Dogs are welcome inside the minimal, light-filled space. It''s never too loud or crowded, which suits nervous small dogs well.', 'A calm specialty café where tiny dogs can relax under the table while you enjoy excellent coffee.', 'yes', 'no', 'yes', 'no', 'yes', 'no', 'no', 'yes', 'yes', 'yes', 'low', 'very_quiet', 'yes', 'no', 'no', 'yes', 'yes', 'Any weekday morning', 'Single-origin coffee, pastries, toasties', '££', 'warm_little_welcome', 78, ARRAY['Warm Little Welcome', 'Little paws welcome inside', 'Quiet corner available'], ARRAY[]::text[], 'personal_visit', '2026-07-02'),

-- EDINBURGH
('the-dog-house-edinburgh', 'The Dog House', 'pub', 'published', 'Scotland', 'City of Edinburgh', 'Edinburgh', 'EH3 8BP', 55.9545, -3.2030, 'A pub named for dog lovers in Edinburgh New Town with dogs welcome everywhere and a dedicated dog menu.', 'The clue is in the name. The Dog House actively celebrates dogs with a dedicated dog menu, water stations and treats at the bar. The atmosphere is relaxed and spacious with plenty of room for small dogs.', 'Literally named for dogs — genuinely one of the most welcoming pubs for tiny dogs in Scotland.', 'yes', 'yes', 'yes', 'no', 'yes', 'yes', 'no', 'yes', 'yes', 'yes', 'low', 'moderate', 'yes', 'yes', 'no', 'no', 'yes', 'yes', 'yes', 'Weekday lunchtimes', 'Craft beers, pub food, dog menu available', '££', 'tiny_dog_favourite', 92, ARRAY['Tiny Dog Favourite', 'Little paws welcome inside', 'Treats behind the bar', 'Best for a calm lunch'], ARRAY[]::text[], 'personal_visit', '2026-06-20'),

('lowdown-coffee-edinburgh', 'Lowdown Coffee', 'cafe', 'published', 'Scotland', 'City of Edinburgh', 'Edinburgh', 'EH1 1QS', 55.9500, -3.1920, 'A specialty coffee bar on George IV Bridge with a warm welcome for dogs inside the compact space.', 'A small but perfectly formed specialty coffee shop near the Royal Mile. Dogs are welcome inside and the baristas always acknowledge four-legged visitors. Great espresso and cakes.', 'A cosy coffee spot where your tiny dog will be greeted warmly. Compact but never feels unwelcoming.', 'yes', 'no', 'yes', 'no', 'yes', 'no', 'no', 'yes', 'yes', 'no', 'low', 'relaxed', 'yes', 'yes', 'no', 'no', 'no', 'yes', 'yes', 'Morning for quietest experience', 'Specialty coffee, cakes, light bites', '££', 'warm_little_welcome', 72, ARRAY['Warm Little Welcome', 'Little paws welcome inside', 'Treats behind the bar'], ARRAY[]::text[], 'venue_confirmation', '2026-06-10'),

-- BRISTOL
('the-grain-barge-bristol', 'The Grain Barge', 'pub', 'published', 'South West', 'Bristol', 'Bristol', 'BS1 6XL', 51.4480, -2.6080, 'A converted barge on the Floating Harbour with dogs welcome on the top deck and inside the bar.', 'A unique Bristol experience — a converted grain barge permanently moored on the harbour. Dogs are welcome inside the cosy bar and on the open-air top deck. Watch the harbour life while your tiny dog watches the seagulls.', 'A characterful floating pub where dogs are welcome. The enclosed top deck is perfect for small dogs on a sunny day.', 'yes', 'yes', 'no', 'no', 'yes', 'no', 'yes', 'yes', 'unknown', 'yes', 'low', 'moderate', 'yes', 'no', 'no', 'yes', 'yes', 'Sunny weekday afternoons', 'Craft ales, burger menu, Sunday roasts', '££', 'warm_little_welcome', 74, ARRAY['Warm Little Welcome', 'Little paws welcome inside', 'Enclosed little garden'], ARRAY[]::text[], 'personal_visit', '2026-06-22'),

('pinkmans-bakery-bristol', 'Pinkmans Bakery', 'cafe', 'published', 'South West', 'Bristol', 'Bristol', 'BS8 1PH', 51.4550, -2.6050, 'A popular Clifton bakery and café with dogs welcome inside and exceptional sourdough.', 'Pinkmans is a Bristol institution for bread and brunch. Dogs are welcome inside the spacious ground floor. Tables are well-spaced and the atmosphere is busy but not overwhelming for a confident small dog.', 'A fantastic brunch spot that welcomes dogs. Best for confident tiny dogs as it can get lively at weekends.', 'yes', 'yes', 'yes', 'no', 'no', 'yes', 'no', 'yes', 'no', 'yes', 'low', 'lively', 'yes', 'no', 'no', 'yes', 'yes', 'Early weekday mornings before the brunch rush', 'Sourdough, pastries, brunch, specialty coffee', '££', 'dog_friendly', 66, ARRAY['Little paws welcome inside', 'Warm welcome, small tables'], ARRAY[]::text[], 'personal_visit', '2026-07-05'),

